import threading
from quota import Limiter

class Clock:
    def __init__(self): self.t = 1000.0
    def __call__(self): return self.t

# contention across all five decision kinds at once, on distinct keys
lim = Limiter(Clock())
for k in ["a","b","p","w"]:
    lim.configure(k, {"capacity": 100000, "refill_per_second": 0.0})
for hk in ["h1","h2"]:
    lim.configure(hk, {"capacity": 100000, "refill_per_second": 0.0})
lim.configure_window("w", {"window_seconds": 60, "max_events": 100000})

N = 200
errs = []
def run(fn):
    try:
        for _ in range(N): fn()
    except BaseException as e:
        errs.append(e)

fns = [
    lambda: lim.check("a", 1),
    lambda: lim.hierarchy_check(["h1","h2"], 1),
    lambda: lim.reserve("b", 1, 3600),
    lambda: lim.hierarchy_reserve(["h1","h2"], 1, 3600),
    lambda: lim.window_check("w"),
]
threads = [threading.Thread(target=run, args=(f,)) for f in fns for _ in range(8)]
for t in threads: t.start()
for t in threads: t.join()
print("errors:", errs)
m = lim.metrics()["decisions"]
for name in ["check","hierarchy_check","reservation","hierarchy_reservation","window_check"]:
    tot = m[name]["allowed"] + m[name]["over_quota"]
    print(name, m[name], "total == 8*N =", tot == 8*N)
